package ru.ryadom.calendar;
import android.app.*;import android.content.*;import android.os.Build;import androidx.test.ext.junit.runners.AndroidJUnit4;import androidx.test.platform.app.InstrumentationRegistry;import org.junit.Test;import org.junit.runner.RunWith;import org.json.*;import static org.junit.Assert.*;
@RunWith(AndroidJUnit4.class)
public class DeletionFailureTest {
 @Test public void failingGetItemDoesNotBlockSnapshotAndRetriesLater()throws Exception{
  assertTrue(Build.HARDWARE.equals("ranchu")||Build.HARDWARE.equals("goldfish"));Instrumentation ins=InstrumentationRegistry.getInstrumentation();Context c=ins.getTargetContext();ins.getUiAutomation().adoptShellPermissionIdentity("android.permission.POST_NOTIFICATIONS");
  try{while(Sync.busy.get())Thread.sleep(50);long now=System.currentTimeMillis();Event missing=new Event();missing.id="missing";missing.source="failure-test";missing.calendar="main";missing.title="Synthetic missing";missing.start=now+86400000;missing.end=missing.start+3600000;Event current=Event.from(missing.json());current.id="current";current.title="Synthetic current";Event updated=Event.from(current.json());updated.title="Updated title";Providers.Result result=new Providers.Result();result.events.add(updated);result.calendars.put("main","Synthetic calendar");JSONObject account=new JSONObject().put("id",missing.source).put("type","ews").put("active",true);
   Store.edit(c,d->{d.put("accounts",new JSONArray().put(account));d.put("events",new JSONArray().put(missing.json()).put(current.json()));d.put("statuses",new JSONObject().put(missing.source,new JSONObject().put("success",now-60000).put("rangeEnd",now+31L*86400000)));d.put("deletionChecks",new JSONObject());d.put("pendingCancellations",new JSONObject());d.put("pendingNew",new JSONObject());d.put("seen",new JSONObject().put(current.key(),now));d.put("cancellations",true);});NotificationManager manager=c.getSystemService(NotificationManager.class);manager.cancelAll();
   Sync.run(c,(context,a,from,to)->result,(context,a,e)->{throw new Providers.Failure("Synthetic GetItem failure",true);});JSONObject data=Store.read(c);assertEquals("Updated title",Store.array(data,"events").getJSONObject(0).getString("title"));assertEquals(1,Store.array(data,"events").length());assertEquals("",Store.object(data,"statuses").getJSONObject(missing.source).getString("error"));assertTrue(Store.array(data,"accounts").getJSONObject(0).getBoolean("active"));assertEquals(1,Store.object(data,"deletionChecks").length());assertEquals(0,manager.getActiveNotifications().length);
   Sync.run(c,(context,a,from,to)->result,(context,a,e)->true);assertEquals(0,Store.object(Store.read(c),"deletionChecks").length());assertEquals(1,manager.getActiveNotifications().length);assertEquals(Notices.CANCELLED,manager.getActiveNotifications()[0].getTag());manager.cancelAll();Sync.run(c,(context,a,from,to)->result,(context,a,e)->{throw new AssertionError("Should not recheck delivered deletion");});assertEquals(0,manager.getActiveNotifications().length);
  }finally{ins.getUiAutomation().dropShellPermissionIdentity();Store.edit(c,d->d.put("accounts",new JSONArray()).put("events",new JSONArray()).put("deletionChecks",new JSONObject()));}
 }
}
